(function(){
const getToken=()=>localStorage.getItem('admin_token');
const headers=()=>({Authorization:`Bearer ${getToken()||''}`,'Content-Type':'application/json'});
const el=id=>document.getElementById(id);
let selected=null, requests=[];
function statusBadge(s){return `<span class="badge">${s||'open'}</span>`}
async function api(url, opts={}){const token=getToken(); const r=await fetch(url,{...opts,headers:{...(opts.body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:`Bearer ${token}`}:{})}}); const t=await r.text(); let j; try{j=JSON.parse(t)}catch{j={raw:t}} if(!r.ok) throw new Error(j.error||j.detail||r.statusText); return j;}
function renderList(){el('list').innerHTML=requests.map(r=>`<div class="request ${selected&&selected.id===r.id?'active':''}" data-id="${r.id}"><div style="display:flex;justify-content:space-between;gap:8px"><strong>${r.title}</strong>${statusBadge(r.status)}</div><div class="muted">${r.page||''}</div><div class="muted">${r.requester_email||''}</div></div>`).join(''); document.querySelectorAll('.request').forEach(n=>n.onclick=()=>selectRequest(n.dataset.id));}
function renderDetail(){if(!selected){el('detail').innerHTML=''; return;} el('detailTitle').textContent=selected.title; const p=selected.callback_payload||{}; el('detail').innerHTML=`<div><strong>Page:</strong> ${selected.page||''}</div><div><strong>Email:</strong> ${selected.requester_email||''}</div><div><strong>Status:</strong> ${statusBadge(selected.status)}</div><div style="margin-top:10px"><strong>Description</strong><pre>${selected.description||''}</pre></div><div class="links">${p.previewLink?`<a href="${p.previewLink}" target="_blank">Preview</a>`:''}${p.deliverableLink?`<a href="${p.deliverableLink}" target="_blank">Deliverable</a>`:''}${p.reviewLink?`<a href="${p.reviewLink}" target="_blank">Review</a>`:''}</div><div style="display:flex;gap:8px;margin-top:12px"><button id="closeBtn">Close</button><button id="reopenBtn" class="secondary">Reopen</button><button id="approveBtn" class="ghost">Approve</button><button id="revBtn" class="ghost">Request Changes</button></div>`; const closeBtn=el('closeBtn'); if(closeBtn) closeBtn.onclick=()=>act('close'); const reopenBtn=el('reopenBtn'); if(reopenBtn) reopenBtn.onclick=()=>act('reopen'); const approveBtn=el('approveBtn'); if(approveBtn) approveBtn.onclick=()=>act('approve'); const revBtn=el('revBtn'); if(revBtn) revBtn.onclick=()=>act('request-revision');}
async function load(){requests=await api('/api/admin/edit-requests'); renderList(); if(selected){selected=requests.find(r=>r.id===selected.id)||selected; if(selected.id) selected=await api('/api/admin/edit-requests/'+selected.id); renderDetail();}}
async function selectRequest(id){selected=await api('/api/admin/edit-requests/'+id); renderList(); renderDetail();}
async function act(action){if(!selected)return; await api('/api/admin/edit-requests/'+selected.id+'?action='+action,{method:'PUT'}); await load();}
async function createReq(){await api('/api/admin/edit-requests',{method:'POST',body:JSON.stringify({title:el('title').value,page:el('page').value,description:el('description').value,requester_email:el('email').value,preview_approval_needed:el('approval').value==='true',attachments:[]})}); el('title').value=''; el('page').value=''; el('description').value=''; el('email').value=''; await load();}
el('refreshBtn').onclick=load; el('createBtn').onclick=createReq; load().catch(err=>{el('detail').innerHTML='<pre>'+err.message+'</pre>';});
})();